def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # For each row/column, fill any background cell lying strictly between
    # two foreground markers. Preserve marker cells; inserted cells are 2.
    for r in range(h):
        p=[c for c,v in enumerate(grid[r]) if v==1]
        for a,b in zip(p,p[1:]):
            for c in range(a+1,b):
                if grid[r][c]==8: out[r][c]=2
    for c in range(w):
        p=[r for r in range(h) if grid[r][c]==1]
        for a,b in zip(p,p[1:]):
            for r in range(a+1,b):
                if grid[r][c]==8: out[r][c]=2
    return out
